with valid as (select id, account_id, txn_type, amount, txn_time, merchant, date_format(txn_time, 'MMM yyyy') as txn_time_label, trim(txn_type) as clean_txn_type, coalesce(merchant, 'OTHER') as resolved_merchant from transactions where merchant is not null), flagged as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time, id) > interval 30 days then 1 else 0 end as session_start_flag from valid), sessions_transactions as (select *, sum(session_start_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged) select case when amount >= 4200 then 'PREMIUM' else 'STANDARD' end as amount_tier, date_trunc('week', txn_time) as week_start, sum(case when merchant = 'Shell' then amount else 0 end) as shell_amount, round(avg(session_start_flag), 2) as avg_session_start_flag, percent_rank() over (partition by case when amount >= 4200 then 'PREMIUM' else 'STANDARD' end order by sum(case when merchant = 'Shell' then amount else 0 end) desc) as shell_amount_percent_rank from sessions_transactions group by 1, 2 having round(avg(session_start_flag), 2) > 0;
